import 'package:ziesocial/core/constants.dart';

class PostModel {
  final int id;
  final String username;
  final String userAvatar;
  final String location;
  final String imageUrl;
  int likesCount;
  final int commentsCount;
  final String caption;
  final String timeAgo;
  bool isLiked;
  bool isBookmarked;

  PostModel({
    required this.id,
    required this.username,
    required this.userAvatar,
    required this.location,
    required this.imageUrl,
    required this.likesCount,
    required this.commentsCount,
    required this.caption,
    required this.timeAgo,
    this.isLiked = false,
    this.isBookmarked = false,
  });

  factory PostModel.fromJson(Map<String, dynamic> json) {
    final author = json['author'] ?? {};

    return PostModel(
      id: json['id'] is int ? json['id'] : int.parse(json['id'].toString()),
      username: author['username'] ?? 'User',
      userAvatar: ApiConstants.getImageUrl(author['avatar']),
      location: author['name'] ?? '',
      imageUrl: ApiConstants.getImageUrl(json['image']),
      likesCount: json['like_count'] ?? 0,
      commentsCount: json['comment_count'] ?? 0,
      caption: json['caption'] ?? '',
      timeAgo: _formatDate(json['create_date']),
      isLiked: json['is_liked'] ?? false,
      isBookmarked: false,
    );
  }

  static String _formatDate(String? rawDate) {
    if (rawDate == null || rawDate.isEmpty) return 'RECENT';
    try {
      final date = DateTime.parse(rawDate);
      final diff = DateTime.now().difference(date);
      if (diff.inMinutes < 60) {
        return '${diff.inMinutes == 0 ? 1 : diff.inMinutes} MINUTES AGO';
      } else if (diff.inHours < 24) {
        return '${diff.inHours} HOURS AGO';
      } else {
        return '${diff.inDays} DAYS AGO';
      }
    } catch (_) {
      return 'RECENT';
    }
  }
}

class StoryModel {
  final String username;
  final String avatarUrl;
  final bool isUser;

  StoryModel({
    required this.username,
    required this.avatarUrl,
    required this.isUser,
  });
}

class UserModel {
  final String id;
  final String username;
  final String email;
  final String name;
  final String avatar;
  final String bio;

  UserModel({
    required this.id,
    required this.username,
    required this.email,
    required this.name,
    required this.avatar,
    required this.bio,
  });

  factory UserModel.fromJson(Map<String, dynamic> json) {
    return UserModel(
      id: json['id'].toString(),
      username: json['username'] ?? '',
      email: json['email'] ?? '',
      name: json['name'] ?? '',
      avatar: json['avatar'] ?? '',
      bio: json['bio'] ?? '',
    );
  }
}

class ApiConstants {
  static String get baseUrl {
    return "https://giver-suds-identity.ngrok-free.dev/ziesocial";
  }

  static String get apiBaseUrl => '$baseUrl/api';

  static String get login => '$apiBaseUrl/auth/login.php';
  static String get register => '$apiBaseUrl/register.php';
  static String get createPost => '$apiBaseUrl/posts/create.php';
  static String get readPosts => '$apiBaseUrl/posts/read.php';
  static String get toggleLike => '$apiBaseUrl/likes/toggle.php';

  // Helper untuk mendapatkan full URL dari path gambar di server
  static String getImageUrl(String? relativePath) {
    if (relativePath == null || relativePath.isEmpty) {
      return 'https://picsum.photos/seed/placeholder/600/600';
    }
    if (relativePath.startsWith('http://') ||
        relativePath.startsWith('https://')) {
      return relativePath;
    }
    return '$baseUrl/$relativePath';
  }
}

import 'dart:convert';
import 'package:http/http.dart' as http;

class ApiClient {
  Map<String, dynamic> _handleResponse(http.Response response) {
    final data = jsonDecode(response.body);

    if (response.statusCode >= 200 && response.statusCode < 300) {
      return Map<String, dynamic>.from(data);
    }

    throw Exception(data['message'] ?? 'Terjadi kesalahan pada server.');
  }

  Future<Map<String, dynamic>> get(
    String url, {
    Map<String, String>? headers,
  }) async {
    final response = await http.get(
      Uri.parse(url),
      headers: {'Content-Type': 'application/json', ...?headers},
    );

    return _handleResponse(response);
  }

  Future<Map<String, dynamic>> post(
    String url, {
    Map<String, dynamic>? body,
    Map<String, String>? headers,
  }) async {
    final response = await http.post(
      Uri.parse(url),
      headers: {'Content-Type': 'application/json', ...?headers},
      body: jsonEncode(body),
    );

    return _handleResponse(response);
  }

  Future<Map<String, dynamic>> upload(
    String url, {
    required String filePath,
    required String fieldName,
    Map<String, String>? fields,
  }) async {
    final request = http.MultipartRequest('POST', Uri.parse(url));

    request.files.add(await http.MultipartFile.fromPath(fieldName, filePath));

    if (fields != null) {
      request.fields.addAll(fields);
    }

    final streamedResponse = await request.send();

    final response = await http.Response.fromStream(streamedResponse);

    return _handleResponse(response);
  }
}

